package config

// Defaults returns the values Load fills in when kongtrol.yaml leaves a
// field out (applyDefaults on an empty config). The config reference
// (docs/CONFIG.md, generated by internal/docgen) reads its "default"
// column from here, so the documented defaults are the ones the code uses.
func Defaults() Config {
	var c Config
	applyDefaults(&c)
	return c
}
